```json
{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(CAST(c.duration AS DOUBLE)-CAST(s.duration AS DOUBLE),0.5)/1e6 gap_p50_ms, approx_quantile(CAST(c.duration AS DOUBLE)-CAST(s.duration AS DOUBLE),0.95)/1e6 gap_p95_ms, approx_quantile(s.duration,0.5)/1e6 srv_p50 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY 1,2 HAVING count(*)>=5 ORDER BY gap_p95_ms DESC LIMIT 20",
          "claim": "Only ts-travel2-service to ts-route-service calls show a large client-minus-server gap (p95 about 526 ms) while route server time stays about 1.5 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50, approx_quantile(s.duration,0.5)/1e6 server_p50 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel2-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY 1,2 ORDER BY n DESC",
          "claim": "travel2's other outbound calls (basic, seat, train) keep client and server times close, so the slowdown is specific to the route GET path."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name LIKE '%admin_trip' GROUP BY 1,2,3",
          "claim": "travel2 admin_trip server requests reach p95 about 2 seconds in the abnormal period, with the time spent in adminQueryAll."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-admin-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50, approx_quantile(s.duration,0.5)/1e6 server_p50 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-admin-travel-service' AND s.service_name='ts-travel2-service' GROUP BY 1,2,3",
          "claim": "ts-admin-travel-service's GET calls to travel2 admin_trip slowed to about 229 ms p50, from about 26 ms in normal."
        }
      ]
    },
    {
      "from": "ts-admin-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 p50, approx_quantile(duration,0.95)/1e6 p95 FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%admintravel%' GROUP BY 1,2",
          "claim": "ts-ui-dashboard's admintravel endpoint p50 rises to about 466 ms and p95 to about 3.3 s, from about 61 ms in normal."
        }
      ]
    }
  ]
}
